"use client";
import { useState } from "react";
import Link from "next/link";
import { bidActivity, clarification, demoAward, reviewProgress, vendorInvoices, vendorMilestones, vendorTender } from "@/data/vendor-workspace";
import styles from "./workspace.module.css";

function Header({context,title,copy}:{context:string;title:string;copy:string}){return <header className={styles.header}><div><p>{context}</p><h1>{title}</h1><span>{copy}</span></div></header>};function Tag({children}:{children:React.ReactNode}){return <span className={styles.tag}>{children}</span>};function Panel({title,children}:{title:string;children:React.ReactNode}){return <section className={styles.panel}><h2>{title}</h2>{children}</section>};function Tabs({items,active,set}:{items:string[];active:string;set:(x:string)=>void}){return <div className={styles.tabs} role="tablist">{items.map(x=><button role="tab" aria-selected={active===x} onClick={()=>set(x)} key={x}>{x}</button>)}</div>};function Table({headers,children}:{headers:string[];children:React.ReactNode}){return <div className={styles.tableWrap}><table><thead><tr>{headers.map((h,i)=><th key={i}>{h}</th>)}</tr></thead><tbody>{children}</tbody></table></div>}

export function BidActivity(){const[filter,setFilter]=useState("All"),[detail,setDetail]=useState(true),[file,setFile]=useState<File|null>(null),[responded,setResponded]=useState(false);const filters=["All","Submitted","Under Review","Clarification Required","Shortlisted","Decision Published"];return <div className={styles.page}><Header context="Bid tracking" title="Bid Activity" copy="Track submitted proposals, clarification requests, procurement review progress and published decisions."/><section className={styles.metrics}>{[["Submitted Bids","02"],["Under Review","01"],["Action Required","01"],["Decisions Published","01"]].map(x=><article key={x[0]}><small>{x[0]}</small><strong>{x[1]}</strong><span>Frontend demo value</span></article>)}</section><Tabs items={filters} active={filter} set={setFilter}/><Panel title="Submitted Bid Activity"><Table headers={["Tender","Submitted Version","Bid Value","Submission Status","Review Stage","Action Required","Updated",""]}><tr><td><strong>{vendorTender.shortTitle}</strong><small>{vendorTender.reference}</small></td><td>{bidActivity.submittedVersion}</td><td>{bidActivity.bidValue}</td><td><Tag>{bidActivity.submissionState}</Tag></td><td>{bidActivity.procurementStage}</td><td>Clarification response</td><td>17 Sep 2026</td><td><button className={styles.link} onClick={()=>setDetail(!detail)}>{detail?"Close":"View"}</button></td></tr></Table></Panel>{detail&&<><div className={styles.grid}><Panel title="BPHU Bid Activity"><dl className={styles.details}><dt>Vendor</dt><dd>Apex Infra</dd><dt>Bid Value</dt><dd>{bidActivity.bidValue}</dd><dt>Proposal Version</dt><dd>{bidActivity.submittedVersion}</dd><dt>Submission State</dt><dd>{bidActivity.submissionState}</dd><dt>Timestamp</dt><dd>{bidActivity.submittedAt}</dd><dt>Current Stage</dt><dd>{bidActivity.procurementStage}</dd><dt>Version Status</dt><dd>{bidActivity.lockState}</dd><dt>Integrity</dt><dd>{bidActivity.integrity}</dd></dl></Panel><Panel title="Vendor-Visible Review Progress"><div className={styles.list}>{reviewProgress.map(x=><div key={x[0]}><strong>{x[0]}</strong><Tag>{x[1]}</Tag></div>)}</div><p className={styles.notice}>Demo workflow state. No rankings, agent scores, committee notes, competitor information, or private decision reasoning are exposed.</p></Panel></div><div className={styles.grid}><Panel title="Clarification Request"><dl className={styles.details}><dt>Clarification</dt><dd>{clarification.id}</dd><dt>Subject</dt><dd>{clarification.subject}</dd><dt>Requested By</dt><dd>{clarification.requestedBy}</dd><dt>Related Requirement</dt><dd>{clarification.requirement}</dd><dt>Response Deadline</dt><dd>{clarification.deadline}</dd><dt>Status</dt><dd>{clarification.status}</dd></dl><p className={styles.body}>{clarification.request}</p><label className={styles.drop}>Attach Similar Work Completion Certificate<input type="file" accept="application/pdf,.pdf" onChange={e=>setFile(e.target.files?.[0]??null)}/></label>{file&&<p className={styles.notice}>{file.name} · selected locally, not uploaded</p>}<label className={styles.form}>Response<textarea rows={4} placeholder="Prepare formal clarification response"/></label><button className="button" onClick={()=>setResponded(true)}>Submit Demo Response</button>{responded&&<p className={styles.notice}>Local demo state only. No response was sent to a procurement system.</p>}</Panel><Panel title="Communication History"><div className={styles.activity}>{[["17 Sep · 10:30","Clarification issued"],["17 Sep · 14:10","Vendor response prepared"],["17 Sep · 14:22","Supporting document selected locally"],["Pending","Response submission"]].map(x=><div key={x[0]+x[1]}><time>{x[0]}</time><span>{x[1]}</span></div>)}</div><p className={styles.notice}>If shortlisted, the vendor will see only that its proposal progressed—not position, competitors, scores, or private review information.</p></Panel></div></>}</div>}

export function AwardsContracts(){const[tab,setTab]=useState("Overview"),[ack,setAck]=useState(false),[file,setFile]=useState<File|null>(null);const tabs=["Overview","Awards","Contracts & Delivery","Invoices"];return <div className={styles.page}><Header context="Awards & delivery" title="Awards & Contracts" copy="Review procurement decisions, acknowledge awards and manage contractual delivery obligations."/><section className={styles.metrics}>{[["Award Notifications","01"],["Awaiting Acknowledgement",ack?"00":"01"],["Active Contracts","01"],["Pending Delivery Actions","02"]].map(x=><article key={x[0]}><small>{x[0]}</small><strong>{x[1]}</strong><span>Simulated TenderIQ state</span></article>)}</section><Tabs items={tabs} active={tab} set={setTab}/>{tab==="Overview"&&<><p className={styles.notice}><strong>Demo Award Scenario:</strong> Apex Infra is used only for a simulated TenderIQ workflow and is not claimed as the historical winner of the real tender.</p><Panel title="Award Overview"><Table headers={["Tender","Award Value","Notification","Acknowledgement","Contract","Next Action"]}><tr><td><strong>{vendorTender.shortTitle}</strong><small>{vendorTender.reference}</small></td><td>{demoAward.value}</td><td>{demoAward.notification}</td><td>{ack?"Acknowledged · Demo":demoAward.acknowledgement}</td><td>{demoAward.contract}</td><td><button className={styles.link} onClick={()=>setTab("Awards")}>Review Award →</button></td></tr></Table></Panel></>}{tab==="Awards"&&<div className={styles.grid}><Panel title="BPHU Demo Award"><dl className={styles.details}><dt>Tender</dt><dd>{vendorTender.title}</dd><dt>Reference</dt><dd>{vendorTender.reference}</dd><dt>Organization</dt><dd>{vendorTender.organization}</dd><dt>Award Value</dt><dd>{demoAward.value}</dd><dt>Award / LOI</dt><dd>{demoAward.notification}</dd><dt>Performance Security</dt><dd>{demoAward.performanceSecurity}</dd><dt>Completion</dt><dd>{demoAward.completion}</dd><dt>Acknowledgement</dt><dd>{ack?"Acknowledged · Frontend Demo":demoAward.acknowledgement}</dd></dl><button className="button" onClick={()=>setAck(true)}>Acknowledge Award</button></Panel><Panel title="Acknowledgement Workflow"><div className={styles.activity}>{["Organization issues Award / LOI","Vendor receives notification","Vendor reviews","Vendor acknowledges","Contract preparation / activation"].map((x,i)=><div key={x}><time>0{i+1}</time><span>{x}</span></div>)}</div><p className={styles.notice}>Acknowledgement is frontend-only. No transaction or electronic signature occurred.</p></Panel></div>}{tab==="Contracts & Delivery"&&<><Panel title="Contract / Work Order"><dl className={styles.details}><dt>Work Order ID</dt><dd>{demoAward.workOrder}</dd><dt>Tender</dt><dd>{vendorTender.shortTitle}</dd><dt>Organization</dt><dd>{vendorTender.organization}</dd><dt>Contract Value</dt><dd>{demoAward.value}</dd><dt>Start</dt><dd>{demoAward.start}</dd><dt>Target Completion</dt><dd>{demoAward.target}</dd><dt>Status</dt><dd>Active · Demo</dd><dt>Performance Security</dt><dd>{demoAward.performanceSecurity}</dd></dl></Panel><div className={styles.grid}><Panel title="Construction Milestones"><div className={styles.list}>{vendorMilestones.map(x=><div key={x[0]}><strong>{x[0]}</strong><Tag>{x[1]}</Tag></div>)}</div></Panel><Panel title="Milestone Evidence"><p className={styles.body}>Attach progress, measurement, completion or inspection evidence for the selected milestone.</p><label className={styles.drop}>Attach Evidence PDF<input type="file" accept="application/pdf,.pdf" onChange={e=>setFile(e.target.files?.[0]??null)}/></label>{file&&<p className={styles.notice}>{file.name} · selected locally, not uploaded</p>}<div className={styles.activity}>{["Award","Contract","Mobilization","Construction","Inspection","Completion"].map((x,i)=><div key={x}><time>0{i+1}</time><span>{x}</span></div>)}</div></Panel></div></>}{tab==="Invoices"&&<><Panel title="Vendor Invoices"><Table headers={["Invoice","Related Milestone","Amount","Submitted","Matching Status","Finance Status"]}>{vendorInvoices.map(x=><tr key={x[0]}>{x.map((v,i)=><td key={i}>{i===0?<strong>{v}</strong>:v}</td>)}</tr>)}</Table></Panel><div className={styles.grid}><Panel title="Three-Way Matching"><div className={styles.list}>{[["Work Order",demoAward.workOrder],["Milestone / Completion Evidence","Partial Match"],["Vendor Invoice",vendorInvoices[0][0]]].map(x=><div key={x[0]}><strong>{x[0]}</strong><Tag>{x[1]}</Tag></div>)}</div><p className={styles.notice}>Frontend demo matching state; no AI or backend verification has run.</p></Panel><Panel title="Payment & Performance"><dl className={styles.details}><dt>Payment Status</dt><dd>Ready for Finance Review</dd><dt>Milestone Adherence</dt><dd>On track · Demo</dd><dt>Quality / Acceptance</dt><dd>Inspection pending</dd><dt>Compliance</dt><dd>Requirements met to date</dd><dt>Responsiveness</dt><dd>Within agreed timelines</dd></dl><p className={styles.notice}>TenderIQ does not automatically approve payment. Finance and procurement remain responsible.</p></Panel></div></>}<nav className={styles.tabs} aria-label="Award links"><Link href="/vendor/activity">View Bid Activity</Link><Link href="/vendor/opportunities/bphu">View Tender</Link><Link href="/vendor/proposals/bphu">View Proposal</Link></nav></div>}
